import{_ as o,o as a,c as e,a2 as r}from"./chunks/framework.DYYBR_aZ.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"其他/英语练习.md","filePath":"其他/英语练习.md"}'),d={name:"其他/英语练习.md"};function n(l,t,u,i,s,p){return a(),e("div",null,[...t[0]||(t[0]=[r('<p>情况：我现在缺少的可能不是复杂的英语句子，而是英语交流中的“连接词”和“功能性短句”（Conversational Chunks）。</p><p>与其记住 100 个零散的英语表达，不如掌握 20 个高频场景的标准表达流程（SOP）</p><p>因为真实交流中，很多场景确实具有很强的重复性。</p><p>但SOP 是帮助你降低表达成本的，不是限制你的。</p><p>过去是看到一个英语表达就想记下来；现在是先识别场景，再掌握这个场景的标准表达。</p><h3 id="寒暄" tabindex="-1">寒暄 <a class="header-anchor" href="#寒暄" aria-label="Permalink to &quot;寒暄&quot;">​</a></h3><p>其实有一个非常固定的表达模式：回答 + 反问对方。</p><table tabindex="0"><thead><tr><th>老师问</th><th>你的回答</th></tr></thead><tbody><tr><td><strong>How are you?</strong></td><td>I&#39;m good, thanks. How about you?</td></tr><tr><td>How are you doing?</td><td>I&#39;m doing well, thanks. And you?</td></tr><tr><td>How&#39;s your day going?</td><td>Pretty good so far. How about yours?</td></tr><tr><td>How was your day?</td><td>It was good, thanks. How about yours?</td></tr><tr><td>How have you been?</td><td>I&#39;ve been doing well. How about you?</td></tr></tbody></table><p>我最推荐你记住：</p><blockquote><p>I&#39;m doing well, thanks. How about you?</p></blockquote><p>这句话几乎可以应付大多数日常寒暄。</p><p>另外几个很自然的短句：</p><ul><li>Pretty good! 挺好的！</li><li>Not bad. 还不错。</li><li>A little tired, but I&#39;m good. 有点累，不过还好。</li></ul><h3 id="提出请求" tabindex="-1">提出请求 <a class="header-anchor" href="#提出请求" aria-label="Permalink to &quot;提出请求&quot;">​</a></h3><p>Could I ask you a quick favor? 我可以请你帮个小忙吗？</p><p>Could I ask you a quick question? 我可以快速问你一个问题吗？</p><p>Could I ask you a quick favor? Could you correct me whenever I make a mistake?</p><p>我可以请你帮个小忙吗？我犯错误的时候，你能随时纠正我吗？</p><h3 id="还有问题吗" tabindex="-1">还有问题吗 <a class="header-anchor" href="#还有问题吗" aria-label="Permalink to &quot;还有问题吗&quot;">​</a></h3><p>Yes, I have one question.</p><p>Not at the moment, thanks. 暂时没有</p><h3 id="询问" tabindex="-1">询问 <a class="header-anchor" href="#询问" aria-label="Permalink to &quot;询问&quot;">​</a></h3><p>Is our course coming to an end？ 我们的课程要结束了吗</p>',23)])])}const _=o(d,[["render",n]]);export{c as __pageData,_ as default};
